import java.net.*;import java.net.http.*;import java.time.*;class Solution{static HttpRequest request(URI uri){if(!uri.getScheme().equals("https"))throw new IllegalArgumentException("https required");return HttpRequest.newBuilder(uri).timeout(Duration.ofSeconds(3)).header("Accept","application/json").GET().build();}static HttpClient client(){return HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).followRedirects(HttpClient.Redirect.NORMAL).build();}}
